// POST JSON: { invoices:[], faculty_forms:[], booking_requests:[], schedule_bookings:[], reference_students:[] }
const p = $input.first().json.body ?? $input.first().json;
const invoices=p.invoices??[], forms=p.faculty_forms??[], requests=p.booking_requests??[], schedules=p.schedule_bookings??[], refs=p.reference_students??[];
const by=(a,k)=>new Map(a.map(x=>[String(x[k]),x]));
const im=by(invoices,'id'), rm=by(refs,'student_id'), existing=by(requests,'invoice_id');
const seen=new Set(), ready=[], exceptions=[], backlog=[];
function flag(f,code,reason,owner,next){exceptions.push({invoice_id:String(f.invoice_id??''),form_id:String(f.id??''),reason_code:code,reason,owner,next_action:next});}
for(const f of forms){const iid=String(f.invoice_id??''), i=im.get(iid), s=rm.get(String(f.student_id)); if(seen.has(iid)){flag(f,'DUPLICATE_FORM','Multiple forms reference one invoice.','Operations','Deduplicate by invoice_id; do not create another booking.');continue;} seen.add(iid); if(!i){flag(f,'INVOICE_NOT_FOUND','Invoice reference absent from invoices.','Operations + Teacher','Correct invoice ID and verify gateway record.');continue;} if(i.payment_status!=='Paid'){flag(f,i.payment_status==='Failed'?'PAYMENT_FAILED':'PARTIAL_PAYMENT',`Gateway status is ${i.payment_status}.`,'Finance/Ops','Verify settlement; no booking until full payment.');continue;} if(!s){flag(f,'STUDENT_REFERENCE_MISSING','Student absent from active master.','Operations','Verify active enrolment.');continue;} const fields=['user_id','student_id','class_id','educator_id']; const bad=fields.filter(k=>String(i[k])!==String(f[k])); if(bad.length){flag(f,'IDENTITY_OR_OWNERSHIP_MISMATCH',`Invoice/form mismatch: ${bad.join(', ')}.`,'Operations','Resolve against canonical student record.');continue;} if(String(s.educator_id)!==String(f.educator_id)||String(s.class_id)!==String(f.class_id)){flag(f,'MASTER_DATA_MISMATCH','Teacher/course differs from active master.','Academic Ops','Validate current class ownership.');continue;} if(f.parent_mobile && i.mobile && f.parent_mobile!==i.mobile){flag(f,'PARENT_CONTACT_MISMATCH','Payer/form contact differs; masked values cannot prove identity.','Parent Support','Verify guardian using trusted channel.');continue;} if(Number(i.net_amount)!==Number(f.amount_paid)){flag(f,'AMOUNT_MISMATCH','Net invoice amount differs from form amount.','Finance + Teacher','Correct amount and verify discounts.');continue;} if(f.continue_same_batch!=='Yes'){flag(f,'BATCH_CHANGE_REQUEST','A batch change was requested.','Scheduling Ops','Get parent confirmation and check capacity.');continue;} if(String(f.current_classbatch_id)!==String(s.current_classbatch_id)){flag(f,'CURRENT_BATCH_MISMATCH','Current batch differs from master.','Scheduling Ops','Validate latest enrolment.');continue;} if(f.preferred_days!==s.batch_days||f.preferred_time_slot!==s.batch_start_time){flag(f,'SCHEDULE_PREFERENCE_MISMATCH','Days/time do not match current batch.','Scheduling Ops','Confirm intended schedule.');continue;} if(Number(s.active_students_count)>=Number(s.max_batch_size)){flag(f,'BATCH_AT_CAPACITY','Batch is full.','Scheduling Ops','Find approved alternative; never overbook.');continue;} if(existing.has(iid)){flag(f,'BOOKING_REQUEST_ALREADY_EXISTS',`Booking request ${existing.get(iid).id} already exists.`,'Operations','Idempotently continue existing request.');continue;} ready.push({invoice_id:iid,form_id:String(f.id),student_id:String(f.student_id),user_id:String(f.user_id),class_id:String(f.class_id),educator_id:String(f.educator_id),classbatch_id:String(s.current_classbatch_id),sessions_count:Number(f.sessions_purchased),preferred_days:f.preferred_days,preferred_time:f.preferred_time_slot,decision:'AUTO_APPROVE_READY'});}
for(const i of invoices){if(i.payment_status==='Paid'&&i.is_renewal==='Yes'&&!seen.has(String(i.id))) flag(i,'PAID_INVOICE_NO_FORM','Paid renewal has no faculty form.','Teacher + Operations','Remind teacher; escalate after 12h.');}
for(const r of requests){if(r.request_status!=='Completed'||r.batch_allocated!=='Yes')backlog.push({booking_request_id:r.id,invoice_id:r.invoice_id,status:r.request_status,reason_code:'BOOKING_ALLOCATION_PENDING',owner:'Scheduling Ops'});}
const messages=exceptions.map(e=>({invoice_id:e.invoice_id,audience:e.owner.includes('Parent')?'parent':e.owner.includes('Teacher')?'teacher':'ops',reason_code:e.reason_code,draft:`Hello, we are completing renewal ${e.invoice_id}. We need to verify ${e.reason_code} before confirming classes. Please reply or contact Bambinos support. We will update you shortly.`}));
return [{json:{summary:{invoice_rows:invoices.length,faculty_forms:forms.length,booking_requests:requests.length,schedule_rows:schedules.length,auto_approve_ready:ready.length,exceptions:exceptions.length,open_booking_requests:backlog.length},auto_approved_ready:ready,exceptions,message_drafts:messages,booking_backlog:backlog,warning:'Prototype only: persist decisions to production DB with idempotency keys; do not send messages or create schedules until downstream controls are configured.'}}];
